// SEGMENT TREE — array representation
class SegmentTree {
    constructor(nums) {
        this.n = nums.length;
        this.tree = new Array(4 * this.n).fill(0);
        this.build(nums, 1, 0, this.n - 1);
    }

    // BUILD: O(n) — compute all nodes bottom-up
    build(nums, node, l, r) {
        if (l === r) {
            this.tree[node] = nums[l]; // leaf: store element
            return;
        }
        const mid = Math.floor((l + r) / 2);
        this.build(nums, 2*node,   l,     mid); // left child
        this.build(nums, 2*node+1, mid+1, r);   // right child
        this.tree[node] = this.tree[2*node] + this.tree[2*node+1]; // combine
    }

    // NODE COUNT VERIFICATION:
    // n=8 leaves: complete binary tree has 15 nodes (2^4 - 1)
    // Array needs indices 1..15, size 16 = 2*8 = 2n  (exact for power of 2)
    // n=5 leaves: ceil(log2(5)) = 3, tree has height 3
    //   Max index = 2^(3+1) - 1 = 15, need array size 16 < 4*5 = 20 ✓
    // 4n always sufficient: covers worst case
}

// WHY 4n: detailed derivation
// A segment tree for n elements has height h = ceil(log2(n))
// Maximum number of nodes = 2^(h+1) - 1
// For n not a power of 2: 2^(h+1) <= 4n (by definition of ceil(log2))
// For n=5: h=3, 2^4=16 <= 4*5=20 ✓
// For n=9: h=4, 2^5=32 <= 4*9=36 ✓

// AGGREGATE FUNCTIONS (the tree generalises over these):
// Sum: tree[node] = tree[left] + tree[right]
// Min: tree[node] = Math.min(tree[left], tree[right])
// Max: tree[node] = Math.max(tree[left], tree[right])
// GCD: tree[node] = gcd(tree[left], tree[right])
// XOR: tree[node] = tree[left] ^ tree[right]
// All are associative: f(f(a,b),c) == f(a,f(b,c))

const st = new SegmentTree([1,3,5,7,9,11]);
console.log(st.tree.slice(1, 12)); // First 11 entries of tree array

