// SEGMENT TREE WITH POINT UPDATE AND RANGE QUERY
class SegmentTree {
    constructor(nums) {
        this.n = nums.length;
        this.tree = new Array(4 * this.n).fill(0);
        this.build(nums, 1, 0, this.n - 1);
    }

    build(nums, node, l, r) {
        if (l === r) { this.tree[node] = nums[l]; return; }
        const mid = Math.floor((l + r) / 2);
        this.build(nums, 2*node, l, mid);
        this.build(nums, 2*node+1, mid+1, r);
        this.tree[node] = this.tree[2*node] + this.tree[2*node+1];
    }

    // POINT UPDATE: set nums[idx] = val — O(log n)
    update(idx, val, node=1, l=0, r=this.n-1) {
        if (l === r) {
            this.tree[node] = val; // leaf: update value
            return;
        }
        const mid = Math.floor((l + r) / 2);
        if (idx <= mid) this.update(idx, val, 2*node,   l,     mid);
        else            this.update(idx, val, 2*node+1, mid+1, r);
        this.tree[node] = this.tree[2*node] + this.tree[2*node+1]; // recompute
    }

    // RANGE QUERY: sum of nums[ql..qr] — O(log n)
    query(ql, qr, node=1, l=0, r=this.n-1) {
        if (qr < l || r < ql) return 0;  // fully outside: return identity
        if (ql <= l && r <= qr) return this.tree[node]; // fully inside
        const mid = Math.floor((l + r) / 2);
        return this.query(ql, qr, 2*node,   l,     mid) +
               this.query(ql, qr, 2*node+1, mid+1, r);
    }
}

