// SEGMENT TREE WITH LAZY PROPAGATION (range add, range sum)
class LazySegTree {
    constructor(nums) {
        this.n = nums.length;
        this.tree = new Array(4*this.n).fill(0);
        this.lazy = new Array(4*this.n).fill(0); // pending add values
        this.build(nums, 1, 0, this.n-1);
    }

    build(nums, node, l, r) {
        if (l === r) { this.tree[node] = nums[l]; return; }
        const mid = Math.floor((l+r)/2);
        this.build(nums, 2*node, l, mid);
        this.build(nums, 2*node+1, mid+1, r);
        this.tree[node] = this.tree[2*node] + this.tree[2*node+1];
    }

    // PUSH DOWN: propagate lazy tag to children
    pushDown(node, l, r) {
        if (this.lazy[node] === 0) return; // nothing to propagate
        const mid = Math.floor((l+r)/2);
        const leftLen  = mid - l + 1;
        const rightLen = r - mid;
        // Left child: add lazy*leftLen to its sum; propagate tag
        this.tree[2*node]   += this.lazy[node] * leftLen;
        this.lazy[2*node]   += this.lazy[node];
        // Right child
        this.tree[2*node+1] += this.lazy[node] * rightLen;
        this.lazy[2*node+1] += this.lazy[node];
        this.lazy[node] = 0; // reset this node's tag
    }

    // RANGE UPDATE: add delta to all elements in [ql, qr] — O(log n)
    rangeUpdate(ql, qr, delta, node=1, l=0, r=this.n-1) {
        if (qr < l || r < ql) return; // fully outside
        if (ql <= l && r <= qr) {      // fully inside
            this.tree[node] += delta * (r - l + 1); // update sum
            this.lazy[node] += delta;               // mark lazy
            return;
        }
        this.pushDown(node, l, r); // propagate before going deeper
        const mid = Math.floor((l+r)/2);
        this.rangeUpdate(ql, qr, delta, 2*node,   l,     mid);
        this.rangeUpdate(ql, qr, delta, 2*node+1, mid+1, r);
        this.tree[node] = this.tree[2*node] + this.tree[2*node+1];
    }

    // RANGE QUERY: sum of [ql, qr] — O(log n)
    rangeQuery(ql, qr, node=1, l=0, r=this.n-1) {
        if (qr < l || r < ql) return 0;
        if (ql <= l && r <= qr) return this.tree[node];
        this.pushDown(node, l, r); // propagate before going deeper
        const mid = Math.floor((l+r)/2);
        return this.rangeQuery(ql, qr, 2*node, l, mid) +
               this.rangeQuery(ql, qr, 2*node+1, mid+1, r);
    }
}

const lst = new LazySegTree([1,2,3,4,5]);
console.log(lst.rangeQuery(0,4)); // 15
lst.rangeUpdate(1,3,10);          // add 10 to elements [1,2,3] -> [1,12,13,14,5]
console.log(lst.rangeQuery(0,4)); // 45
console.log(lst.rangeQuery(1,3)); // 39 (12+13+14)

