// RANGE SUM QUERY - MUTABLE (#307)
class NumArray {
    constructor(nums) {
        this.n = nums.length;
        this.tree = new Array(4*this.n).fill(0);
        this._build(nums, 1, 0, this.n-1);
    }

    _build(nums, node, l, r) {
        if (l === r) { this.tree[node] = nums[l]; return; }
        const mid = (l+r)>>1;
        this._build(nums, 2*node, l, mid);
        this._build(nums, 2*node+1, mid+1, r);
        this.tree[node] = this.tree[2*node] + this.tree[2*node+1];
    }

    update(index, val, node=1, l=0, r=this.n-1) {
        if (l === r) { this.tree[node] = val; return; }
        const mid = (l+r)>>1;
        if (index <= mid) this.update(index, val, 2*node, l, mid);
        else              this.update(index, val, 2*node+1, mid+1, r);
        this.tree[node] = this.tree[2*node] + this.tree[2*node+1];
    }

    sumRange(left, right, node=1, l=0, r=this.n-1) {
        if (right < l || r < left) return 0;
        if (left <= l && r <= right) return this.tree[node];
        const mid = (l+r)>>1;
        return this.sumRange(left, right, 2*node, l, mid) +
               this.sumRange(left, right, 2*node+1, mid+1, r);
    }
}

