// FENWICK TREE (Binary Indexed Tree) — O(log n) per operation
class FenwickTree {
    constructor(n) {
        this.n = n;
        this.bit = new Array(n+1).fill(0); // 1-indexed
    }

    // lowbit: isolate lowest set bit
    // 6 = 0110 -> lowbit = 0010 = 2
    // 8 = 1000 -> lowbit = 1000 = 8
    lowbit(i) { return i & (-i); }

    // UPDATE: add delta to position i (1-indexed)
    update(i, delta) {
        while (i <= this.n) {
            this.bit[i] += delta;
            i += this.lowbit(i); // move to parent (add lowbit)
        }
    }

    // PREFIX QUERY: sum of positions 1..i
    query(i) {
        let sum = 0;
        while (i > 0) {
            sum += this.bit[i];
            i -= this.lowbit(i); // move to previous bucket (remove lowbit)
        }
        return sum;
    }

    // RANGE QUERY: sum of positions l..r
    rangeQuery(l, r) {
        return this.query(r) - this.query(l-1);
    }
}

// BUILD from array in O(n log n)
function buildFenwick(nums) {
    const ft = new FenwickTree(nums.length);
    for (let i = 0; i < nums.length; i++) {
        ft.update(i+1, nums[i]); // 1-indexed
    }
    return ft;
}

