// SPARSE TABLE for static range minimum — O(n log n) build, O(1) query
function buildSparseTable(arr) {
    const n = arr.length;
    const LOG = Math.floor(Math.log2(n)) + 1;
    const table = Array.from({length:n}, () => new Array(LOG).fill(0));
    // Base: table[i][0] = arr[i]
    for (let i = 0; i < n; i++) table[i][0] = arr[i];
    // Fill: table[i][j] = min of [i, i+2^j)
    for (let j = 1; j < LOG; j++) {
        for (let i = 0; i + (1<<j) <= n; i++) {
            table[i][j] = Math.min(table[i][j-1], table[i + (1<<(j-1))][j-1]);
        }
    }
    return table;
}

function sparseTableQuery(table, l, r) {
    const k = Math.floor(Math.log2(r - l + 1));
    return Math.min(table[l][k], table[r - (1<<k) + 1][k]); // overlap is OK for min
}

